#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""这条缓存答案**现在还能用吗** —— 纯逻辑,零 IO。规格 §13 + 附录 A-3。

## 它防的是哪一族 bug

规格附录 A-3 的「解决什么问题」栏:
> 「**清理期间旧请求回写、旧权限和旧资料复活。**」

而规格 §C.2 的场景表里,这一族占了最多行:入缓存后撤销授权、资料发布与撤回、
清空后旧请求回写、TTL 边界、Redis 逐出但目录仍在、权限服务不可用。
它们的共同点是:**答案还在,而它已经不该被返回了** ——
> 而一条不该返回的答案,和一条正常的答案,**在内容上长得一模一样**。

## 五条判据(每条对着规格里一个场景)

### ① 未知 ≠ 没变 —— 任一必要版本拿不到 → **不可用**

规格 §17.1 第 3 步:「取得该任务所需的权威资料/上下文版本……
**无法确定则绕过**」。所以这里缺一个依赖版本就判不可用,
**不是「假定它没变」**。
> 一个「假定没变」的判断,和一个真的核对过的,**在那个「可用」上长得一模一样**。

### ② 代次必须**完全相等**,不是「≥」

规格 §13.1 第 1 条:清空范围时 `namespace_generation` +1,
**旧请求即使稍后生成完成,也不能向新代次写入**。
写成 `>=` 的话,旧代次的值对新代次就可读了 —— 而那正是「清空后旧请求回写」。

### ③ 过期是**严格小于**,而且命中**不延长**有效期

规格 §10:「首版不提供过期答案继续服务;**命中不自动延长正确性期限**」。
A-3:「当前时间**严格早于**最早有效期」。
所以 `now == expires_at` 算**已过期** —— 边界上偏保守那一边,
因为偏错的代价不对称:多生成一次只多花钱,少失效一次是错答案。

### ④ 撤回**压倒一切**

没过期、代次对、依赖都对 —— 撤回了就是不可用。
规格 §13:「索引未清理完也不能继续返回被撤回内容」;
§13.2:「Redis 中的旧值还在也不能返回」。

### ⑤ 返回**不可用的理由**,不是一个布尔

规格 §7 的概览页要「未命中原因排行」(未配置 / 能力未知 / 过期 /
版本变化 / 权限不符 / 任务不适用 / 后端不可用)。
一个只返回 `False` 的判定,**填不出那张排行** ——
而那张排行正是产品经理用来查「为什么没命中」的唯一入口。

## 它不做什么

- **不鉴权。** 它只核对「授权代次有没有变」;真正的鉴权在交付前那一刻
  (规格 §13.2 的线性化点),由调用方做。
- **不读 Redis、不读库。** 条目和权威状态由调用方取来。
- **不决定要不要重新生成。** 它只说「这条不能用,因为……」。
"""

可用 = "可用"


class 判不了(Exception):
    """输入本身讲不通 —— 当场抛,不返回一个「可用」。"""


# 不可用的原因。**和规格 §7 那张「未命中原因排行」对齐**,不另立一套。
过期 = "已过期"
代次变了 = "命名空间代次变了(范围被清空过)"
授权变了 = "授权代次变了(撤权或权限收窄)"
资料变了 = "依赖的资料版本变了"
被撤回 = "条目已被撤回"
依赖未知 = "有依赖版本拿不到(**未知不等于没变**)"
负载没了 = "目录里有这条,而存储里的负载没了(被逐出)"


def 还能用吗(*, 条目, 权威, 现在):
    """返回 `(能不能用, 原因, 细节)`。`原因` 是 `可用` 或上面那几个常量之一。

    `条目` 要有:`namespace_generation` / `authorization_epoch` /
    `dependencies`(dict:资料清单、检索配置等的 revision)/
    `expires_at` / `revoked`(bool)/ `payload_present`(bool)。

    `权威` 是**现在**的权威状态:同名的 generation / epoch / dependencies。

    ⚠️ **只报第一条不可用的原因,而且顺序是有意的**:
    撤回 → 代次 → 授权 → 资料 → 过期 → 负载。
    先报撤回而不是先报过期,因为**「撤回了」比「过期了」要紧** ——
    一条过期的答案只是旧,一条被撤回的答案是**不该存在**。
    排行榜上这两个原因要引向不同的下一步。
    """
    # ⚠️ **每个字段给它自己的理由。** 第一版三个字段共用一句
    # 「缺代次时用 0 顶,会让旧代次的条目看起来是新的」——
    # 而那句话对 `expires_at` **不成立**。
    # > 一句解释错了东西的报错,比不解释更误导人:
    # > 读的人会照着那个错方向去查。
    为什么 = {
        "namespace_generation": "用 0 顶会让**旧代次的条目看起来是新的**",
        "authorization_epoch": "用 0 顶会让**撤权之前的条目通过授权核对**",
        "expires_at": "用一个遥远的时间顶,等于给这条答案**永久有效期**",
    }
    for 名 in 为什么:
        if 名 not in 条目:
            raise 判不了(f"条目缺 `{名}` —— **不拿默认值顶**:{为什么[名]}")
    for 名 in ("namespace_generation", "authorization_epoch"):
        if 权威.get(名) is None:
            raise 判不了(f"权威状态里没有 `{名}` —— 拿不到权威状态时"
                       f"**不许判可用**,由调用方决定绕过还是拒绝")

    细 = {}

    # ④ 撤回压倒一切 —— 即使没过期、代次对、依赖都对
    if 条目.get("revoked"):
        return False, 被撤回, {"⚠️": "Redis 里的旧值还在也不能返回(规格 §13.2)"}

    # ② 代次必须完全相等
    if 条目["namespace_generation"] != 权威["namespace_generation"]:
        return False, 代次变了, {
            "条目的": 条目["namespace_generation"],
            "现在的": 权威["namespace_generation"],
            "⚠️": "**判的是完全相等,不是 `>=`** —— 写成 `>=` 的话旧代次的值"
                  "对新代次就可读了,而那正是「清空后旧请求回写」"}
    if 条目["authorization_epoch"] != 权威["authorization_epoch"]:
        return False, 授权变了, {
            "条目的": 条目["authorization_epoch"],
            "现在的": 权威["authorization_epoch"],
            "⚠️": "**不等待 Redis 物理删除**(规格 §C.2「入缓存后撤销授权」);"
                  "而这只是代次核对,**真正的鉴权在交付前那一刻**"}

    # ① 未知 ≠ 没变
    条依 = dict(条目.get("dependencies") or {})
    权依 = dict(权威.get("dependencies") or {})
    拿不到 = sorted(k for k in 条依 if k not in 权依 or 权依[k] is None)
    if 拿不到:
        return False, 依赖未知, {
            "拿不到的": 拿不到,
            "⚠️": "**未知不等于没变** —— 规格 §17.1:无法确定则绕过。"
                  "假定没变的判断,和真的核对过的,在那个「可用」上长得一样"}
    变了 = sorted(k for k in 条依 if 条依[k] != 权依[k])
    if 变了:
        return False, 资料变了, {
            "变了的": {k: {"条目的": 条依[k], "现在的": 权依[k]} for k in 变了},
            "⚠️": "版本变了就不返回旧结论(规格 §C.2「资料发布与撤回」)"}
    # ⚠️ 权威多出来的依赖**不算变**:这条答案当初没用到它。
    # 反过来算的话,任何新加一个依赖都会让全部旧条目一起失效。
    多出来 = sorted(k for k in 权依 if k not in 条依)
    if 多出来:
        细["权威多出来的依赖"] = 多出来
        细["怎么读"] = ("这条答案当初没用到它们,**所以不算变** —— "
                     "反过来算的话,新加一个依赖会让全部旧条目一起失效")

    # ③ 严格小于;命中不延长
    到 = 条目["expires_at"]
    if 到 is None:
        raise 判不了("`expires_at` 是 None —— **没有有效期不等于永久有效**。"
                   "规格 §10:首版不提供过期答案继续服务,所以它必须有一个到期时间")
    if not (现在 < 到):
        return False, 过期, {
            "到期": 到, "现在": 现在,
            "⚠️": "**严格小于** —— `现在 == 到期` 算已过期。"
                  "边界上偏保守那一边:多生成一次只多花钱,"
                  "少失效一次是**错答案**。而命中**不延长**正确性期限(规格 §10)"}

    # ⑥ 负载没了 —— 目录有记录不等于值还在
    if 条目.get("payload_present") is False:
        return False, 负载没了, {
            "⚠": "规格 §C.2「Redis 逐出但目录仍在」:按未命中处理,"
                 "**不能返回空白伪答案**"}

    return True, 可用, 细


def 能写进去吗(*, 要写的代次, 权威代次, 要写的授权代次, 权威授权代次):
    """生成完了,这个结果**还能写进缓存吗** —— 规格 §13.1 第 2 条。

    ⚠️ 这是和读分开的一次核对:请求开始时代次对,**生成完之后可能已经变了**
    (生成要几秒到几十秒,而清空范围是瞬间的)。
    > 一个只在读的时候核过代次的实现,和一个两头都核的,
    > **在正常情况下长得一模一样** —— 差别只在清空那一瞬间出现。
    """
    if 要写的代次 != 权威代次:
        return False, (f"生成期间命名空间被清空过(开始时 {要写的代次},"
                       f"现在 {权威代次})—— **不写进新代次**(规格 §13.1 第 1 条)")
    if 要写的授权代次 != 权威授权代次:
        return False, (f"生成期间授权变过(开始时 {要写的授权代次},"
                       f"现在 {权威授权代次})—— 返回经过当前权限检查的结果或终止,"
                       f"**禁止缓存旧结果**(规格 §13.1 第 2 条)")
    return True, "可以写"
